(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.2)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.018-t*0.25)*18 + Math.sin(x*0.015+t*0.35)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const w2x = Math.sin(w1x*0.025+t*0.5)*6 + Math.cos(w1y*0.02-t*0.4)*5;
  const w2y = Math.cos(w1y*0.025-t*0.45)*6 + Math.sin(w1x*0.022+t*0.55)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1.2],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2.5],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 3.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 5.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.45+2)*50, 0.11, 2.1, 4.2],
    [400+Math.cos(t*0.55+1)*60, 220+Math.sin(t*0.75+4)*40, 0.085, 1.8, 2.9],
    [200+Math.sin(t*0.42)*110, 10+Math.cos(t*0.62+1)*30, 0.075, 2.4, 1.6],
    [300+Math.cos(t*0.48+3)*90, 230+Math.sin(t*0.38+2)*50, 0.095, 2.0, 3.4]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,ph] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const w = Math.sin(d*f*0.3+t*0.4)*0.15+1;
    aS += Math.sin(d*f*w - t*sp + ph)*w;
    iS += Math.sin(d*f*0.7*w + t*sp*0.6 + 1.5 + ph*0.5)*w;
    cS += Math.cos(d*f*0.5 - t*sp*0.8 + ph*0.3)*w*0.5;
  }
  const n = 10, act=aS/n, inh=iS/n, cor=cS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07+sy*0.05-t*1.8)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.03-ang*5+t*0.9)*0.2;
  const ring = Math.sin(dist*0.08-t*1.5)*Math.exp(-dist*0.005)*0.3;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = (Math.sin(sx*0.4+t*3)*Math.sin(sy*0.4-t*2.5)+Math.sin((sx-sy)*0.3+t*2))*0.08;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + ring + micro*0.5)*2.0);
  const coupled = Math.tanh((cor*0.6 + act*inh*0.4 + spiral*0.2)*1.8);
  const blend = reaction*0.55 + cell*0.15 + coupled*0.2 + micro*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,45,88],[18,95,115],[30,155,140],[80,185,130],
    [170,200,85],[220,175,55],[215,120,60],[180,60,55],[110,30,65],
    [50,18,72],[20,10,55],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sm = f*f*(3-2*f);
  const lum = 0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge = Math.abs(reaction)>0.72?1.18:Math.abs(coupled)>0.6?1.08:1.0;
  const depth = 0.9+Math.sin(dist*0.02-t*0.5)*0.1;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge*depth)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge*depth)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge*depth)|0
  ];
}
